 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The left-hand stack contains framed 3x3 silhouettes. Fill each silhouette
    # with the right-hand object having the same normalized shape.
    objects = {}
    seen = set()
    for r in range(h):
        for c in range(6, w):
            color = grid[r][c]
            if not color or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1,0), (-1,0), (0,1), (0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 6 <= p[1] < w and p not in seen and grid[p[0]][p[1]] == color:
                        seen.add(p)
                        stack.append(p)
            top = min(y for y, x in cells)
            left = min(x for y, x in cells)
            shape = frozenset((y-top, x-left) for y, x in cells)
            objects[shape] = color
    out = [row[:6] for row in grid]
    # Frames are separated by all-border rows; locate their top rows.
    for top in range(h - 4):
        if all(grid[top][c] != 0 for c in range(5)) and all(grid[top+4][c] != 0 for c in range(5)):
            holes = [(r, c) for r in range(top+1, top+4) for c in range(1, 4) if grid[r][c] == 0]
            if not holes:
                continue
            mr = min(r for r, c in holes)
            mc = min(c for r, c in holes)
            shape = frozenset((r-mr, c-mc) for r, c in holes)
            color = objects.get(shape)
            if color is not None:
                for r, c in holes:
                    out[r][c] = color
    return out
